SELECT m.chembl_id, m.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, COALESCE(di.efo_term, di.mesh_heading) AS indication_label, di.max_phase_for_ind FROM molecule_dictionary m JOIN drug_indication di ON m.molregno = di.molregno JOIN compound_structures cs ON m.molregno = cs.molregno WHERE m.max_phase = 4 AND (LOWER(di.efo_term) LIKE '%hypertension%' OR LOWER(di.mesh_heading) LIKE '%hypertension%') ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, indication_curie, indication_label, di.max_phase_for_ind
